"""Model-authored source roles and mechanisms, 2026-10-04. No API generation.
IDs are curated from reading all 344 explicit-field descriptions, not keyword cartesian matching.
Numbers expand SYS identifiers. A group is a candidate role, never proof of field availability.
"""
def ids(s):
 out=[]
 for x in s.split():
  if '-' in x:
   a,b=map(int,x.split('-')); out+=range(a,b+1)
  else: out.append(int(x))
 return sorted(set(out))
