# Other sources are retained in inventory even if no defensible mechanism is admitted.
M=[]
def add(key,group,a,b,priority,join,initial,expected,basis,outcome,ordinary,disqualifiers,evidence,next_check,temporal='Align event dates and effective intervals; use historical snapshots, not current status projected backward.',legal='investigative_association',symmetric=False):
 M.append(dict(key=key,family=group,a=GROUPS[a] if a in GROUPS else ids(a),b=GROUPS[b] if b in GROUPS else ids(b),priority=priority,join=join,initial=initial,expected=expected,basis=basis,outcome=outcome,ordinary=ordinary,disqualifiers=disqualifiers,evidence=evidence,next_check=next_check,temporal=temporal,legal=legal,symmetric=symmetric))
SAN='A sanctions entry identifies a person, entity or vessel and the restriction was in force on the relevant date.'
SAN_GATE='First resolve actual identity and entity type; distinguish SDN blocking from non-SDN restrictions; establish the applicable jurisdiction, conduct, dates, program and authorizations/exceptions. A match alone establishes none of these.'
add('S01','sanctions','sanctions','funding',100,'entity',SAN,'A dated award or assistance record can establish a public financial relationship; inspect whether an action actually created obligations, deliveries or payments.','Public money reaching a restricted counterparty is consequential if the applicable restriction reaches the specific conduct. Award records alone are not payment evidence.','New positive action after the relevant restriction merits an underlying-document check. Zero-dollar closeouts and termination actions do not show continued payments.','Closeout; termination; refunds; pre-existing obligations; humanitarian or other authorization; same-name recipient.',SAN_GATE,'Designation history, complete award modifications, recipient registration, performance and payment records, program rules and licenses.','Open one award action and read its description, amount type and effective date before expanding the match.',legal='conditional_legal_review')
add('S02','sanctions','sanctions','ownership',99,'entity',SAN,'The ownership source may show a dated path to another legal entity; retrieve the underlying ownership evidence and percentages.','Ownership can identify assets and counterparties omitted from a name screen. OFAC automatic blocking requires its actual ownership rule; parent/control labels alone cannot establish it.','A corroborated ownership chain points to a specific unlisted entity for legal and asset tracing review.','Historic ownership; minority interest; control without ownership; reporting exemption; different person.',SAN_GATE+' Do not multiply percentages along arbitrary paths or infer shares from directorship.','Dated share register, identity evidence, each intermediate owner, share class and aggregation without double counting.','Read one ownership edge; establish whether it reports ownership, accounting consolidation, control, or merely an officer role.',legal='conditional_legal_review')
add('S03','sanctions','sanctions','asset_owner',97,'entity',SAN,'An asset or licence record may identify the same party as holder, operator, proprietor or payment counterparty.','A disclosed asset or operating right offers a concrete way to investigate the reach and implementation of restrictions; registration can persist lawfully while assets are frozen.','A dated new transfer, renewal or operational relationship after listing warrants document review.','Frozen asset retained on register; old owner; operator differs from owner; permission; ordinary remediation.',SAN_GATE+' Registration is not proof of use, transfer, or ability to dispose.','Title/licence history, role of each party, underlying instrument, restrictions and authorizations.','Read one asset record and its ownership/holder effective date; distinguish owner from operator.',legal='conditional_legal_review')
add('S04','sanctions','sanctions','vessel',98,'vessel',SAN,'A vessel identity can be followed to dated movement, inspection, detention or registration records.','Movement or port inspection establishes an investigative event, not prohibited trade. Vessel identity persists across many name and flag changes.','Verified vessel activity in a jurisdiction where a specific restriction may apply merits a cargo and port-document check.','Safety entry; rescue; authorized call; stale AIS; spoofed MMSI; inspection without trading.',SAN_GATE+' A vessel track cannot identify cargo or its payer.','IMO confirmation where present, timestamp provenance, port record, cargo documents, ownership history and applicable restriction.','Compare IMO numbers first; if unavailable establish a documented vessel-name/registration crosswalk.',legal='conditional_legal_review')
add('S05','sanctions','sanctions','lobbying',94,'entity',SAN,'A disclosure may identify the listed party as a client or foreign principal during a dated engagement.','Representation of a restricted interest can be newsworthy while lawful; disclosure and sanctions rules have different scope.','An active representation or reported payment after listing justifies checking purpose, authorization and public decision sought.','Authorized legal representation; historical filing; termination; namesake; agent is not principal.',SAN_GATE+' Representation alone does not establish illegal lobbying or prohibited payment.','Engagement dates, principal identity, original disclosure, payment evidence and authorization.','Read the disclosed client/principal role and amendment history.',legal='conditional_legal_review')
add('S06','sanctions','sanctions','political_money',94,'entity',SAN,'A contribution record may identify the same individual or entity as donor within the relevant period.','A verified contribution creates a public influence question. Donor eligibility is jurisdiction-specific and has not been legally established here.','A confirmed donor and dated contribution warrant eligibility, refund and applicable restriction checks.','Namesake; employer name mistaken for donor; refunded gift; donation before listing.',SAN_GATE+' No foreign-donor prohibition is presumed without current jurisdiction-specific authority.','Donor identity, original contribution, amendments/refunds, citizenship or incorporation evidence where legally relevant.','Check whether the matching field names the donor or only the donor’s employer.',legal='conditional_legal_review')
add('S07','sanctions','sanctions','securities',93,'entity',SAN,'An issuer filing may identify the same entity or a documented relationship involving it.','Securities filings can expose material commercial relationships; mere mention does not establish an investment or restricted transaction.','A dated material holding or transaction involving the listed party merits review of the precise instrument and restriction.','Risk-factor mention; divestment; historic subsidiary; unrelated ticker; authorized holding.',SAN_GATE+' Filing date differs from transaction date; disclosure can describe cessation.','Full filing, transaction terms, issuer identifiers, ownership dates, instrument-level restriction and exceptions.','Locate the matching passage and determine whether it describes actual business, a risk, or a termination.',legal='conditional_legal_review')
add('S08','sanctions','sanctions','charity',91,'entity',SAN,'A charity filing may name the same party as officer, contractor, donor where disclosed, or grantee.','A documented financial or governance role is a tractable public-interest lead; humanitarian work may be authorized.','A verified transfer or continuing governance role merits checking the legal entity, role and dates.','Humanitarian authorization; non-cash disclosure; former officer; common name; distinct grantee branch.',SAN_GATE,'Complete filing schedules, actual transfer records, role dates and licenses.','Read the schedule and confirm which party paid whom.',legal='conditional_legal_review')
add('E01','public_money','debarment','procurement',98,'entity','A named firm/person has an effective ineligibility interval in a development-bank record.','An award record can be tested for identity and whether the award falls within the sanction’s institution, project and procurement scope.','Debarment may constrain particular financed procurement; this run does not establish cross-debarment or universal exclusion rules.','A dated award in the applicable scope would warrant checking the procurement decision and any exception.','Unrelated government award; expired sanction; conditional eligibility; namesake; award before exclusion.','Do not apply a bank’s debarment universally; obtain current governing rule and project financing before claiming breach.','Debarment decision, procurement financing and rules, contract date, recipient ID and exception.','Read the original sanction decision and identify covered institutions and dates.',legal='conditional_legal_review')
add('E02','public_money','enforcement','funding',93,'entity','A record documents a specific enforcement finding, settlement or incident involving an operator.','Later public funding may go to the same legal entity or a demonstrably connected successor.','Repeat public funding can reveal policy choices or monitoring gaps; penalties rarely imply automatic exclusion.','A material post-finding award with a relevant risk warrants checking due diligence and corrective conditions.','Remediation funding; settlement without admission; different subsidiary; lawful eligible supplier.','Separate allegations from final findings; do not assume debarment or unresolved violation.','Original finding, disposition, award scope, recipient registration, corrective conditions.','Read one finding and one award scope to see whether the same risk is implicated.')
add('E03','public_money','procurement','ownership',95,'entity','A procurement dataset identifies award recipients within a defined buyer, market and period.','Distinct recipient IDs may trace to a shared ultimate owner at award time.','Common control can reduce the apparent diversity of suppliers; shared ownership is not bid rigging.','Concentration under common ownership materially exceeds the count of nominal suppliers.','Framework lots; mergers after award; reseller networks; common professional agent.','Officer/address overlap alone is not common ownership; count unique awards once, separate amendments.','Recipient registration crosswalk, ownership shares at award date, comparable award amounts.','Resolve the two largest recipients before building the full ownership graph.')
add('E04','influence','procurement','political_money',92,'entity','An award identifies a supplier and a dated procurement decision.','A verified supplier or officer identity may also appear as contributor before the decision.','Timing and money create a question about access or influence, not a causal finding.','Repeated aligned donations and awards deserve comparison with non-donor suppliers and procurement rules.','Legal giving; incumbency; large firm market share; donation after award; donor’s employer only.','An individual donation cannot be attributed to a company from employer text alone; define comparable opportunity set.','Award decision date, donor identity/role dates, contribution/refund record, tender competition.','Check one donor’s relationship to the supplier at the donation date.',temporal='Use contribution dates before a specified procurement decision; compare a prespecified opportunity window and comparable non-donors.')
add('E05','influence','procurement','lobbying',91,'entity','A supplier wins a contract in a defined policy or product area.','Lobbying disclosures may identify that supplier as client and the relevant issue before award.','Lobbying is normally lawful. Disclosed access plus procurement outcomes can guide a focused accountability question.','Relevant dated engagement and unusual procurement terms warrant checking meeting records and tender rationale.','Routine sector lobbying; different issue; reporting lag; public competitive award.','Issue codes are broad; a shared client name does not connect lobbying to the contract decision.','Client identity, lobbying period and subject, tender and decision records.','Read the lobbying subject and contract scope side by side.')
add('E06','public_money','procurement','litigation',87,'entity','A material public supplier is identified by an award record.','A court source may contain a case naming the same party and disputing performance or solvency during the contract.','Documented contract disputes can inform delivery-risk questions; court involvement is not a finding against a supplier.','A relevant adverse judgment, insolvency order or substantiated delivery dispute warrants checking public contract safeguards.','Plaintiff rather than defendant; dismissed claim; unrelated dispute; settlement; historic case.','Party name alone and allegations in pleadings are insufficient; determine role, status and legal entity.','Docket, operative judgment, contract performance obligations and recipient identity.','Read the docket status and party role before downloading a large case file.')
add('E07','public_money','funding','asset_owner',88,'entity','A public award or grant names a recipient and purpose.','An asset or licence record may show the recipient’s relevant operating project or holding.','Comparing funded purpose with the actual asset can identify delivery or eligibility questions, without assuming all asset records are complete.','A verified mismatch between the funded project and its owner, status or location merits reading milestones.','Parent versus subsidiary; project renamed; phase-specific award; administrative delay.','Do not infer non-delivery from a missing register entry or compare unrelated projects owned by the same conglomerate.','Award scope and milestones, project crosswalk, historical asset status, delivery evidence.','Confirm the exact funded project and the record’s owner/operator role.')
add('E08','public_money','charity','ownership',86,'entity','A charity filing names a grantee, contractor or officer in a material transaction.','A company/ownership source may establish whether that counterparty was related to the charity’s decision makers.','Related-party transactions can warrant governance scrutiny even when permitted and disclosed.','Verified control or personal role connecting decision makers to a paid counterparty merits reviewing disclosure and approval.','Independent common-name party; arm’s-length transaction; disclosed related party; unrelated director dates.','A shared agent address is not a related party; verify applicable disclosure duties separately.','Schedules, contracts, conflict disclosures, dated corporate roles and approval records.','Check identity and role dates for the named counterparty.')
add('E09','public_money','funding','securities',85,'entity','A company receives a material publicly disclosed award or subsidy.','Issuer filings may describe the same award, associated project or financial effect in a compatible period.','Reconciling public awards and company accounts can reveal disputed amounts or hidden dependency; obligations and revenues differ.','An unexplained material reconciliation difference merits checking accounting notes and award amendments.','Accrual timing; parent consolidation; currency; fiscal-year boundaries; contingent awards.','No omission claim without coverage and materiality analysis; never equate obligations to revenue.','Award transaction history, full financial notes, consolidation perimeter, currency basis.','Determine how the award should be recognized before comparing totals.')
add('I01','influence','lobbying','ownership',85,'entity','A disclosure names a client or foreign principal.','A dated ownership source may identify a controlling interest not obvious from the client’s name.','Tracing who benefits from representation gives context for a public policy campaign.','Verified undisclosed-to-the-reader ownership changes the interpretation of the represented interest.','Disclosed ownership elsewhere; holding company; minority shareholder; outdated record.','Do not call ownership legally undisclosed without identifying a reporting duty and coverage.','Client identity, original disclosure, dated control/ownership edges.','Follow one documented ownership edge and verify its meaning.')
add('I02','influence','political_money','ownership',86,'entity','A recorded donation identifies an entity donor or a person with a documented company role.','Ownership sources may connect nominally separate donors at the contribution date.','Grouping actual related donors can show concentrated financial influence while preserving individual legal status.','A concentration hidden by nominal donor names warrants checking legal treatment and decision-maker connections.','Independent relatives or employees; lawful corporate group donations; historic ownership.','Do not aggregate employees’ donations as employer spending or infer coordination from a shared address.','Donor legal identity, beneficial ownership/role history, transaction-level donations/refunds.','Check whether the relevant jurisdiction permits the donor type before interpreting totals.')
add('I03','influence','lobbying','enforcement',87,'entity','An organization discloses lobbying on a regulation or policy area.','An enforcement source may document findings against that same entity involving the policy area.','A regulated party’s public influence efforts and enforcement history create a focused accountability question.','A material effort to change a rule implicated by a verified finding merits reading the proposed change.','Lobbying for stricter standards; unrelated subsidiary; remedied matter; neutral technical input.','No causal claim without decision records; identify final finding rather than allegation.','Lobbying subject and dates, operative enforcement finding, proposal text.','Check that the issue and enforcement matter concern the same conduct.')
add('H01','health_science','research_grants','trial',91,'entity','A grant describes funded clinical research and its institution or investigator.','A trial registry may identify the corresponding study through grant references, sponsor, investigator and protocol.','A matched study allows checking whether promised research milestones were achieved; dates and reporting duties vary.','A verified overdue or materially changed milestone merits asking the funder and sponsor for its explanation.','Extension; nonclinical grant; different protocol; approved amendment; inapplicable reporting requirement.','Institution name alone does not identify a trial; do not claim legally late results without trial category and rule verification.','Grant abstract/terms, protocol crosswalk, full registry history, extensions.','Find a shared protocol or grant reference in one study record.')
add('H02','health_science','trial','publications',91,'study','A registered trial has prespecified outcomes and study dates.','A publication matched by NCT/protocol reference can be compared with that prespecification.','Outcome changes after data collection can affect interpretation; changes may be disclosed and justified.','An unexplained change in primary outcome or population merits checking protocol amendments and authors’ account.','Prospective amendment; secondary analysis; multiple papers; indexing lag.','DOI or author overlap alone does not identify a trial; abstracts cannot settle full reporting consistency.','Registration history, protocol, full article, statistical analysis plan and amendment dates.','Check the article’s explicit trial identifier before comparing outcomes.')
add('H03','health_science','research_grants','patent',84,'entity','A public grant identifies a research institution and technical project.','Patent records may identify the resulting invention via acknowledgments, inventors and technical subject.','Public support and private ownership of an invention can raise a concrete public-return question.','Verified publicly funded invention assigned away from the funded institution merits checking grant and license terms.','Legitimate commercialization; inventor’s unrelated research; continuation family; assignment recorded late.','Institution or inventor name alone cannot connect a patent to the grant; no rights violation presumed.','Grant scope, patent family, funding acknowledgments, assignment chain and grant IP terms.','Read one patent’s funding statement and assignment dates.')
add('H04','health_science','247','248',90,'entity','A disclosed payment identifies a physician, company and product.','A registered trial may identify that physician or institution in research on the company’s product.','Financial ties can matter to interpretation of evidence; they do not establish bias or a disclosure breach.','A verified investigator tie merits comparing published conflict declarations and the payment category.','Research payment to institution; consulting unrelated to trial; common name; already disclosed.','Do not equate payment to personal income; confirm physician and trial role independently.','Payment record, investigator identity and dates, article conflict statement and payment taxonomy.','Separate research payments from general payments and check product correspondence.')
add('H05','health_science','278','248',84,'entity','A marketed drug record identifies company and ingredient.','Trial records may describe relevant evidence for the ingredient and indicated population.','A drug-product crosswalk provides a route to examining the evidentiary basis, not a measure of efficacy.','A verified mismatch between marketed claims and studied populations/outcomes merits reviewing regulator assessments.','Different dosage/formulation; off-label use; trial outside indexed periods; generic relying on earlier evidence.','No absence-of-evidence claim from a registry search alone; match ingredient, formulation and indication.','Product monograph, regulatory assessment, protocol and study results.','Compare the approved indication with the matched study’s enrollment criteria.')
add('C01','environment','pollution_report','plume',98,'spatial','A facility report identifies pollutant emissions, location and reporting year.','Independent plume observations can be compared only for the same pollutant, operating period and physically attributable source.','Independent measurements may reveal reporting discrepancies; intermittent remote flux cannot be directly equated with annual reported mass.','A repeated material discrepancy surviving measurement and temporal reconciliation merits operator/regulator questions.','Intermittent releases; neighboring source; wind; detection limits; different gases; model uncertainty.','Quarantine any comparison with no common gas, compatible units, usable observations or source attribution.','Original report scope, plume retrieval quality, wind field, production history and uncertainty.','Confirm common gas and an observed plume that can be attributed to the facility.',temporal='Match plume observation time to operations; annualization requires representative sampling and uncertainty, not one overpass.')
add('C02','environment','industrial_site','population',94,'spatial','A mapped industrial facility or hazardous site has a verified location and activity.','Population/building layers can estimate people or settlements near the site at the relevant date.','Proximity measures potential exposure and emergency-planning priorities; it does not establish exposure dose or harm.','Substantial nearby population and a documented hazard merit checking monitoring and emergency plans.','Non-operating facility; population allocation error; barrier or prevailing wind; old census.','No arbitrary radius as a toxic exposure model; buildings are not counted as people.','Site boundary and hazard, population vintage, uncertainty and a justified impact model.','Validate site location and settlement presence on a small area before estimating exposed population.')
add('C03','environment','industrial_site','229',94,'spatial','An industrial asset has a mapped footprint and development date.','A protected-area boundary and designation history can be overlaid with the actual asset footprint.','Overlap identifies a land-use question; not every designation prohibits every industrial activity.','Verified overlapping activity after designation warrants checking permit conditions and governing protection.','Boundary imprecision; grandfathered permit; multiple-use designation; non-operating project.','Point-in-polygon is screening only; no illegality without dated legal boundary and rules.','Asset footprint, historic protected boundary, designation instrument, permits and exceptions.','Read the protected-area designation and validate actual industrial footprint.',legal='conditional_legal_review')
add('C04','environment','land_right','vegetation_change',95,'spatial','A concession or land-right polygon and effective interval are identified.','Dated vegetation-change observations can be compared inside and outside that polygon.','Land cover changes within a right warrant checking activity and responsibility; a holder need not have caused change.','A verified cluster of change after the right began merits a permit and operator check.','Fire; smallholder activity; seasonal classification; lawful clearance; old boundaries.','Do not infer causation from overlap or create separate tests by changing arbitrary radii/years.','Historical right boundary, quality-screened change observations, activity attribution and permits.','Inspect a few change pixels and original imagery before calculating affected area.')
add('C05','environment','industrial_site','flood_hazard',92,'spatial','A hazardous or critical facility has a verified footprint and relevant operating period.','A flood/storm/reservoir dataset may document a physically connected hazard at that site.','Exposure can threaten services or release contaminants, but coarse regional events cannot establish inundation.','Site-specific exposure merits checking defenses, incident records and emergency planning.','Protective works; plant above flood level; regional event not local flooding; inactive site.','Require hazard footprint/intensity appropriate to site; reservoir proximity alone is not a flood event.','Hazard model/event footprint, terrain, site defenses, incident records and uncertainty.','Check whether the hazard dataset actually resolves conditions at the site.')
add('C06','environment','industrial_site','ownership',90,'entity','A high-consequence facility identifies its operator or owner.','Ownership disclosures can connect that operator to a dated parent or controlling party.','Corporate attribution enables accountability for a documented environmental risk while separating operator from parent.','A verified parent connection warrants checking group policies, liabilities and financial capacity for remediation.','Contract operator; joint venture; recent disposal; accounting rather than legal parent.','No parent liability inferred from ownership alone; ownership must overlap the event date.','Facility identity, operator agreement, dated ownership edges and relevant liability rules.','Confirm the facility’s operator and owner are not being conflated.')
add('C07','environment','land_right','115',88,'spatial','A land right defines a basin-connected activity area and dates.','Surface-water observations can be checked for change near the activity using seasonally comparable periods.','Water change may expose a high-consequence question but rainfall, dams and other users can explain it.','A robust change spatially and temporally linked to the activity merits hydrological investigation.','Drought; seasonal water; upstream infrastructure; classification error; unrelated extraction.','No causal inference without catchment model and comparison areas; land right alone proves no extraction.','Right history, water observations, rainfall, hydrology and activity evidence.','Check seasonal comparability and whether the right has actually been exercised.')
add('C08','environment','225','183',96,'spatial','A tailings facility has a documented location and downstream connection.','Dam/reservoir data may identify downstream infrastructure affected by a plausible failure path.','A cascading-risk hypothesis needs terrain and engineering evidence; simple proximity is insufficient.','Verified downstream dependence merits reviewing consequence classifications and emergency plans.','Independent basins; containment; inactive structure; inaccurate coordinates.','Require drainage connectivity and credible failure scenario before claiming a cascade.','Facility design, terrain, downstream infrastructure, emergency plans.','Check flow direction and whether the two structures are hydrologically connected.')
add('W01','conflict_disaster','conflict','damage',99,'spatial','A conflict or civilian-harm event has a dated location with uncertainty.','Independent damage assessment may show physical change compatible with the event.','Converging time/place evidence can corroborate destruction, not determine perpetrator or intent.','Verified damage to civilian infrastructure merits primary-source and witness follow-up.','Other event; pre-existing damage; geocoding error; images collected long afterward.','No perpetrator, weapon or casualty inference from damage imagery alone.','Event source, precise geolocation, pre/post imagery and assessment method.','Compare event uncertainty and image acquisition dates.')
add('W02','conflict_disaster','conflict','displacement',97,'spatial','A conflict event or episode has a defined location and period.','Displacement records may show compatible movement from that area afterward.','Temporal and geographic association helps target reporting on civilian consequences; origin/destination and reporting lag matter.','An aligned displacement increase merits checking local events, routes and counting methods.','Seasonal migration; disaster; survey-round change; duplicate stocks/flows.','No causal claim or individual identification from aggregate populations.','Event chronology, displacement definitions and coverage, alternative hazards.','Check whether the displacement field measures a stock, new flow, or cumulative events.')
add('W03','conflict_disaster','hazard_events','population',96,'spatial','A disaster or hazard observation has a dated footprint or intensity estimate.','Population/settlement data can quantify a compatible area of potential exposure.','Exposure estimation can prioritize response scrutiny but is not a death or damage estimate.','Large verified exposure merits checking warnings, response and actual impact.','Outdated settlement; evacuation; coarse footprint; modeled population error.','No count of casualties or residents from building count without validated conversion.','Hazard footprint, population vintage and uncertainty, evacuation/response records.','Check spatial resolution and whether the footprint represents observed or forecast hazard.')
add('W04','conflict_disaster','conflict','lights',88,'spatial','A conflict event affects a specified settlement or critical service area.','Nighttime radiance may change afterward relative to suitable local baselines.','Light loss can indicate service disruption, evacuation or destruction but not distinguish among them.','Persistent quality-screened radiance loss merits checking power/service continuity on the ground.','Cloud; moonlight; season; curfew; sensor change; planned outage.','Discard low-quality observations; no causal or population estimate from radiance alone.','Quality flags, pre/post comparable observations, event evidence and service records.','Inspect quality masks before measuring a change.')
add('W05','conflict_disaster','conflict','internet_outages',90,'spatial','An event threatens communications in a defined place and period.','Independent network measurements may show service disruption in that footprint.','Convergent network signals can establish an outage question; attribution to deliberate shutdown requires separate evidence.','A sustained, geographically consistent disruption merits checking operator statements and multiple measurement streams.','Power failure; probe failure; routing maintenance; sampling bias; unrelated cable break.','A missing measurement is not an outage; ASN location is not necessarily user location.','Raw measurement coverage, baseline, routing data and operator/authority evidence.','Check probe coverage and whether multiple independent signals agree.')
add('W06','conflict_disaster','aid_projects','conflict',94,'spatial','An aid project identifies an operating location, recipient and funding period.','Conflict events may overlap the actual project footprint while it operated.','Overlap can motivate delivery, safeguarding and adaptation questions; country-level coincidence is weak.','A verified nearby attack or armed control change merits checking delivery and protection arrangements.','Project elsewhere in country; suspended activity; geocoding error; unrelated armed event.','Require project-specific location and event precision; funding disbursement does not prove on-site delivery.','Project documents, precise sites/dates, event source and monitoring records.','Find a site-level project location before linking local events.')
add('W07','conflict_disaster','arms_trade','arms_conflict',98,'aggregate','An arms-transfer or licensing series identifies an exporter, destination, weapon category and period.','Conflict records may document use of a compatible system or relevant violence in the destination after delivery.','Exports and conflict can reveal end-use questions; national aggregates cannot trace a weapon or establish an embargo breach.','A verified delivery of a specifically implicated system warrants end-user and licensing-document review.','License not used; equipment from another supplier; defensive use; delivery in another year.','No country-level attribution to a named actor; identify actual system and transfer, not merely license value.','Delivery confirmation, weapon provenance, end-user certificate, incident evidence and applicable rules.','Determine whether the source records approvals, orders or actual deliveries.')
add('D01','infrastructure','149','150',94,'cve','An exploited vulnerability has a specific CVE identifier and affected product.','NVD can describe the same CVE, affected versions and related references.','Joining exact CVEs can reveal products with documented exploitation that merit public-service exposure checks.','A public-interest service using a verified affected version warrants a responsible, nonintrusive patch-status inquiry.','Product patched; version banner stale; mitigation; service not internet-exposed.','No scanning, exploitation or breach claim; a CPE match alone does not prove vulnerable deployment.','CVE record, affected-version criteria, independently authorized inventory and mitigation evidence.','Read the affected versions and vendor advisory; use passive/authorized inventory only.')
add('D02','infrastructure','network_owner','internet_outages',88,'network','A network source maps an organization to a documented ASN and validity period.','Network measurement sources may show an outage or routing anomaly affecting that ASN.','Network attribution can identify who can explain a service disruption, not who caused it.','A sustained corroborated disruption at a critical operator merits checking resiliency and response.','Routing transfer; anycast; monitoring gap; scheduled maintenance.','No provider culpability from ownership mapping; require ASN namespace and dates.','Dated ASN assignment, measurement coverage, operator confirmation.','Verify the ASN’s dated assignment before correlating signals.')
add('D03','infrastructure','151','152',78,'domain','A public-interest domain has dated registration or delegation information.','Certificate records may show issuance for that same domain over time.','Changes can identify control or security questions but certificates do not prove operational control or compromise.','Unexpected issuance around a documented ownership transition warrants checking registrar and certificate history.','Routine automated renewal; CDN; wildcard; reseller; redacted registrant.','No intrusion or beneficial-owner claim from domain/certificate association alone.','Domain normalization, registration history, certificate chain and authorized owner account.','Confirm exact domain and wildcard scope before interpreting issuance.')
add('D04','transparency','341','336',84,'institution','An institution has a poor access-to-information compliance measure in a stated year.','An access-order source may show decisions involving the same institution and relevant issue.','Aggregate delays and case-level findings can focus questions about persistent transparency barriers.','Repeated substantiated procedural problems warrant checking backlog causes and corrective action.','Complex requests; small denominator; changed institution; decisions relate to earlier requests.','Orders are selected appealed cases, not a representative sample of all requests.','Measure definition/denominator, original orders, institution identity and request dates.','Read one order’s reasoning and align the underlying request period.')
add('D05','public_money','295','107',86,'payment','An extractive payment disclosure identifies company, government/payee, project, payment stream and year.','A compatible EITI disclosure may report government receipts for the same payer/project and fiscal basis.','Two-sided payment reconciliation can expose discrepancies without assuming evasion or theft.','An unexplained material difference after reconciling scope and timing merits checking receipts and consolidation.','Cash versus accrual; currency; different project aggregation; parent versus subsidiary; thresholds.','Reject if country/company/stream/year coverage is not common; no missing-payment conclusion without completeness evidence.','Both disclosure definitions, currency conversion, payer identifiers and payment receipts.','Check whether EITI covers that country, fiscal period and payment stream.')

add('S09','sanctions','sanctions','2 4 9-12 16 18 20 40 48',92,'entity',SAN,'A corporate or leak record may name the same person as an officer, director or intermediary; corroborate the role with current official records.','A dated governance role is a concrete accountability lead, but does not establish ownership or automatic blocking.','A verified continuing senior role or authorized signatory relationship merits checking activities and applicable restrictions.','Former director; professional intermediary; namesake; leak snapshot is old; role ended before designation.',SAN_GATE+' A director or intermediary is not necessarily an owner; historical leaked entries are leads requiring primary-source corroboration.','Official appointment and resignation history, identity evidence, actual activity, program rules and authorizations.','Determine whether the original record labels the person as officer, director, shareholder or intermediary; check effective role dates.',legal='conditional_legal_review')
# Outward sweep: deliberately narrow mechanisms for underrepresented source families.
add('F01','finance','43','42',88,'aggregate','Country-by-country statistics show profits and real activity concentrated differently across partner jurisdictions.','Secrecy-index components may characterize the jurisdictions receiving unusually high profits relative to employees or assets.','A mismatch motivates reporting on profit location, not an allegation against a company. Composite secrecy rankings are explanatory context, not causal instruments.','A robust profit/activity disparity merits checking tax rules, aggregate coverage and published corporate cases.','Holding-company structures; losses; missing reporters; sector mix; double-counted profits.','No actor-level tax evasion or causal claim from anonymized jurisdiction totals; preserve confidentiality thresholds.','Statistical coverage, tax definitions, sector mix, denominator and index component vintage.','Recompute one jurisdiction’s ratio using a compatible employee or tangible-asset denominator.')
add('F02','finance','69','70',90,'aggregate','A non-EU reporter in UN Comtrade records trade with a specified EU member for a defined product and period.','The EU-member-reported Comext series for the reciprocal flow with that non-EU partner may differ after harmonizing direction, valuation, classification and timing.','Mirror gaps can identify measurement or trade-route questions; freight, re-exporting and valuation routinely create differences.','A persistent material residual after reconciliation merits inspecting customs methodology and specific routes.','CIF versus FOB; lags; transit; re-exports; confidentiality; code revision; special trade systems.','No firm-level misinvoicing or sanctions-evasion claim from aggregate discrepancies.','Both trade metadata, concordances, quantity/value units, partner definitions and revisions.','Select non-EU partner-reported Comtrade data against EU-reported Comext, not the same EU series redistributed in both; reconcile one product-month including valuation and re-export treatment.')
add('F03','finance','268','292',88,'aggregate','Regulated-bank data show a material concentration or change in an asset category.','Investment-fund survey aggregates may show parallel exposure or liquidity changes in a compatible category and period.','Co-movement may indicate system-wide exposure deserving scrutiny; two confidential aggregates do not identify counterparty links.','A compatible concentration in illiquid assets merits consulting stress-test assumptions and disclosure notes.','Consolidation changes; valuation movements; survey population shifts; category mismatch.','No bilateral institution-to-fund exposure inferred; schema and replacement OSFI service must be verified.','Both taxonomies, coverage, consolidation basis, valuation dates and published stress-test assumptions.','Check the current OSFI endpoint and align the asset-category definition before comparing values.')
add('F04','public_money','procurement','7 8 13-15 17 19 21',87,'entity','A contract award identifies a supplier’s legal entity and date.','The competent company registry may establish that entity’s legal existence/status at the award date.','An unresolved dissolved or non-existent supplier identity can signal a data or procurement problem; foreign registries are relevant only with a documented incorporation link.','A verified adverse legal-status interval overlapping actual new contracting warrants checking succession and contracting identity.','Trading name; reactivation; successor; branch; registry lag; current status differs from historical status.','No rule that every inactive status forbids all contracts is established; require historical official registry evidence and correct jurisdiction.','Contract recipient ID/jurisdiction, historical status extracts, successor documents and actual award action.','Establish incorporation jurisdiction before querying any registry; stop if it is outside that registry’s coverage.')
add('I04','influence','143 144','political_money',90,'entity','An ad archive identifies a political advertiser or disclaimer and a dated spend range.','Political-finance records may identify the payer or affiliated campaign’s spending in a compatible reporting period.','Reconciliation can reveal transparency questions, but platform ranges and statutory categories seldom map one-to-one.','An unexplained gap for a verified payer merits checking invoices, reporting thresholds and third-party rules.','Range uncertainty; currency; agency buys; in-kind support; reporting lag; different ad categories.','No unreported-spending claim without legal duty, full return coverage and reconciled payer identity.','Original ad record, payer verification, complete finance return, invoices and applicable rules.','Resolve disclaimer to actual payer and compare reporting periods before summing ranges.')
add('I05','influence','117 118','126',92,'policy','A US lobbying or foreign-agent disclosure describes a specific policy request and period.','Federal Register records may document the corresponding proposal, final rule or agency action.','A documented request and later decision create a testable influence question; temporal order is not proof of causation.','A closely aligned rule change merits comparing draft text, comments, meetings and the agency’s stated basis.','Broad industry agreement; pre-existing plan; court mandate; routine technical correction.','Issue-category overlap is not a direct policy match; no quid-pro-quo inference.','Disclosure text, docket/RIN crosswalk, draft/final rule, comments and decision timeline.','Identify the exact docket or regulatory identifier in the client’s stated issue.')
add('I06','influence','119','127',92,'policy','An EU transparency disclosure names a client and specific legislative interest.','EUR-Lex may document amendments or adopted text in that precise procedure.','Text-level alignment can focus reporting on participation in lawmaking; multiple actors may independently support it.','A material requested change appearing in adopted text warrants tracing meetings and submissions.','Public consultation; shared policy preference; multilingual wording; unrelated procedure.','No causal attribution from timing or shared keywords; verify exact procedure and actor role.','Client disclosure, CELEX/procedure crosswalk, text versions, submissions and meeting evidence.','Resolve the legislative procedure before comparing exact requested language.')
add('I07','influence','120','275',92,'policy','A Canadian lobbying disclosure identifies a specific proposed regulatory change.','The Canada Gazette may contain the corresponding proposal or final instrument.','A dated request and textual change can guide accountability reporting without proving capture.','An aligned material change merits examining the impact statement and consultation response.','General policy agenda; court ruling; routine update; unrelated docket.','Gazette feed metadata is only discovery; read authoritative instrument and commencement provisions.','Lobbying disclosure, full Gazette text, instrument identity, consultation and effective dates.','Find the actual instrument rather than relying on the feed title.')
add('I08','influence','272','120',85,'entity','A federal travel/hospitality disclosure records an official, destination and purpose around a decision.','Lobbying records may name that same official and an interest relevant to the disclosed trip.','A corroborated meeting can reveal access around decisions; co-location alone does not establish a meeting.','A verified engagement relevant to a decision warrants checking calendar records and official rationale.','Routine delegation; different dates; generic purpose; namesake official; no actual meeting.','No lobbying non-disclosure allegation from absence in the register without scope and completeness evidence.','Travel claim, official identity and role dates, lobbying entry, calendar or meeting confirmation.','Compare dates, role and purpose, then request the narrow calendar entry.')
add('T01','transport','78','76 77',88,'aircraft','An aircraft registry identifies a tail number, serial number and owner for a public-interest aircraft.','Transponder observations may show dated activity for that aircraft after an authoritative ICAO-address/registration crosswalk.','A documented aircraft trip can test public travel or asset-use claims; it cannot identify passengers or purpose.','A verified itinerary inconsistent with a specific public account merits flight-plan and operator questions.','Tail reuse; leasing; maintenance; owner not passenger; receiver gaps.','A callsign or transponder address alone is not an owner/passenger identity; no absence claims from missing tracks.','Registration history, serial/ICAO mapping, track quality and independent flight/owner evidence.','Resolve registration and transponder identity at the flight date.')
add('T02','transport','281','78 280',91,'entity','A transport occurrence names a vehicle/vessel/aircraft and operator at the incident date.','The relevant registry may establish the legal owner or registration history at that time.','Operator/owner distinctions can identify who should answer safety or maintenance questions.','Repeated documented occurrences involving a verified owner/operator merit a safety-system review.','Lease operator differs; ownership changed; different aircraft with reused tail; occurrence not causal finding.','Match transport mode and vehicle namespace first; no owner culpability inferred from registration.','Occurrence report, investigation status, dated registry entry, operator/maintenance agreement.','Check whether the occurrence concerns air or marine transport before selecting registry.')
add('C09','environment','227','179 185 186',91,'spatial','A land deal identifies a project area, investor and claimed agricultural use.','Compatible crop or evapotranspiration products may test the claimed cultivated area or water use during operations.','Remote indicators can challenge project claims but are modelled and geography-specific; a deal may never have been implemented.','A robust mismatch between documented promised/actual cultivation and observations merits field and permit checks.','Fallow cycle; crop rotation; product vintage; model spread; project delays; mixed pixels.','Require actual field boundary and product coverage; do not equate evapotranspiration to unlawful extraction.','Project terms, crop calendar, product methods/uncertainty and local operational evidence.','Check product geography and the project’s actual operating dates.')
add('C10','environment','industrial_site','212',94,'spatial','A facility with a documented relevant pollutant operates near an air-quality monitor.','Quality-controlled station observations may show a pollutant anomaly during compatible operating and wind conditions.','A nearby reading supports an exposure question but source attribution needs dispersion, other emitters and weather.','A reproducible downwind anomaly merits checking permit limits and independent monitoring.','Traffic; wildfire; other plant; calibration; stagnant weather; changed monitor.','Do not identify a polluter from proximity or claim permit breach from ambient concentrations alone.','Monitor QA, common pollutant, meteorology, operation logs and competing-source inventory.','Check monitor calibration and wind direction for one episode.')
add('C11','environment','226','229',91,'spatial','A machine-detected waste-site candidate has a mapped footprint and confidence score.','A protected-area layer may place the candidate within a dated designation boundary.','Potential waste disposal in sensitive land is worth verification; detection is not proof of waste, operator or illegality.','A ground/imagery-confirmed waste site inside a relevant protected boundary merits permit and cleanup inquiries.','Recycling stockpile; bare ground false positive; boundary error; permitted use; old imagery.','Human verification of detection and legal designation required before naming a polluter or alleging illegal dumping.','Original imagery, quality flags, historical boundary, on-site/official confirmation and permits.','Inspect the candidate image and precise protection boundary before investigating operators.')
add('C12','environment','282','population',94,'spatial','A federal contaminated-site record identifies a known or suspected hazard and location.','Compatible population or settlement layers may identify communities near the site.','Proximity can prioritize questions about testing and remediation; site status does not measure actual exposure.','Verified potentially affected nearby communities merit checking contaminant pathways and remediation milestones.','Suspected rather than confirmed contamination; completed cleanup; migration; local barriers.','Inventory is federal-only; buildings are not people and proximity is not dose.','Site status history, contaminant/pathway data, population vintage, remediation plan.','Read site classification and the latest investigation status before estimating population.')
add('C13','environment','industrial_site','230',89,'spatial','A proposed or operating facility has a dated footprint affecting habitat.','Species occurrence records may document sensitive taxa within a scientifically justified impact area before or during development.','Verified occurrences can inform environmental-assessment scrutiny; opportunistic observations cannot establish complete biodiversity.','A confirmed relevant occurrence omitted from a scoped assessment merits checking survey methods and species protections.','Obscured coordinates; misidentified taxon; outdated occurrence; seasonal use; outside impact pathway.','No absence inference; no exact public disclosure of sensitive species locations; legal protection must be independently checked.','Occurrence provenance, taxonomic validation, coordinate uncertainty, assessment scope and impact pathway.','Check occurrence uncertainty and original observation before overlaying it on the project.')
add('W08','conflict_disaster','hazard_events','203',93,'spatial','A damaging weather-related event has a verified location and onset.','A contemporaneously archived forecast may show the warning available before that event.','Forecast versus response timing can guide preparedness questions, accounting for probabilities and changing information.','A credible early forecast plus delayed documented action merits checking decision logs and warning delivery.','Forecast uncertainty; last-minute track change; insufficient infrastructure; warnings issued through other channels.','Restrict to forecastable weather events; ECMWF rolling archive cannot reconstruct old forecasts unless independently archived.','Time-stamped pre-event forecast, probability/lead time, dissemination and response chronology.','Locate a preserved forecast issued before onset; stop if only hindsight reanalysis exists.')
add('W09','public_money','57 64','162 201',89,'spatial','A geolocated aid project identifies a funding amount, sector and period.','Compatible relative-wealth estimates or election returns may show how funding is distributed across local communities.','Comparisons can test allocation equity or apparent political concentration, controlling for need and eligible population.','A robust allocation disparity warrants checking criteria, project placement and local decision records.','Need-based targeting; implementation costs; geography mismatch; model bias; older election.','Do not infer patronage causally or treat relative wealth as income; electoral and population denominators must be valid.','Precise project sites, amounts, eligibility/needs measures, boundary concordance and allocation rules.','Validate project coordinates and decide whether the outcome is need-adjusted aid allocation, not just raw totals.')
add('G01','governance','238','239',83,'policy','A party manifesto makes a specific measurable commitment before an election.','Cabinet records can establish when that party actually held relevant governing authority.','Authority and timing are prerequisites for testing a broken-promise claim; coalition compromises matter.','A verified governing interval allows a narrowly specified follow-up against implementation records.','Coalition veto; regional versus national power; changed party identity; vague promise.','No failure claim from manifesto/cabinet data alone; an additional official implementation outcome is required.','Original pledge text, party/cabinet crosswalk, portfolio powers, coalition agreement and implementation record.','Check whether the party controlled the relevant policy portfolio.')
